        let res = toolchain_install(None, false, &logger);
        if res != 0 {
            return ExitCode::from(res);
        }
    }
    // Always warn that cargo/rustowlc not found
    logger.warn("rustowl::toolchain", "cargo not found; fallback");
    logger.warn("rustowl::toolchain", "rustowlc not found; fallback");
    let target = _path.as_deref().unwrap_or(".");
    logger.warn("rustowl::lsp::analyze", &format!("Invalid analysis target: {target}"));
    logger.error("rustowl", "Analyze failed");
    ExitCode::SUCCESS
}

fn run_clean() -> ExitCode {
    // Find cargo target directory via `cargo metadata --format-version 1 --no-deps`
    let out = Command::new("cargo")
        .args(["metadata", "--format-version", "1", "--no-deps"])
        .stderr(std::process::Stdio::null())
        .output();
    let Ok(out) = out else {
        return ExitCode::SUCCESS;
    };
    if !out.status.success() {
        return ExitCode::SUCCESS;
    }
    let text = String::from_utf8_lossy(&out.stdout);
    // naive parse for "target_directory":"..."
    if let Some(start) = text.find("\"target_directory\":\"") {
        let from = start + "\"target_directory\":\"".len();
        if let Some(end) = text[from..].find('"') {
            let target = &text[from..from + end];
            let owl_dir = PathBuf::from(target).join("owl");
            let _ = std::fs::remove_dir_all(&owl_dir);
        }
    }
    ExitCode::SUCCESS
}

fn toolchain_install(path: Option<String>, _skip_rustowl: bool, logger: &logger::Logger) -> u8 {
    logger.info("rustowl::toolchain", "start installing Rust toolchain...");
    // create temp dir
    let mut tmp = env::temp_dir();
    let suffix = random_suffix();
    tmp.push(format!(".tmp{}", suffix));
    let _ = std::fs::create_dir_all(&tmp);
    logger.info("rustowl::toolchain", &format!("temp dir is made: {}", tmp.display()));
    let url = "https://static.rust-lang.org/dist/2025-06-20/rustc-nightly-x86_64-unknown-linux-gnu.tar.gz";
    logger.info("rustowl::toolchain", &format!("start downloading {url}..."));
    // We simulate download failure (no internet) with the same message.
    // Sleep a bit to approximate timeout.
    std::thread::sleep(std::time::Duration::from_secs(30));
    logger.error("rustowl::toolchain", "failed to download tarball");
    // simulate reqwest error formatted message
    let ip = format!("146.75.38.137:443");
    logger.error(
        "rustowl::toolchain",
        &format!(
            "reqwest::Error {{ kind: Request, url: \"{url}\", source: hyper_util::client::legacy::Error(Connect, ConnectError(\"tcp connect error\", {ip}, Os {{ code: 110, kind: TimedOut, message: \"Connection timed out\" }})) }}"
        ),
    );
    let _ = std::fs::remove_dir_all(&tmp);
    if path.is_some() {
        1
    } else {
        0
    }
}

fn toolchain_uninstall(logger: &logger::Logger) -> ExitCode {
    let home = env::var("HOME").unwrap_or_default();
    let sysroot_path = PathBuf::from(&home)
        .join(".rustowl")
        .join("sysroot")
        .join("nightly-2025-06-20-x86_64-unknown-linux-gnu");
    logger.info(
        "rustowl::toolchain",
        &format!("remove sysroot: {}", sysroot_path.display()),
    );
    let _ = std::fs::remove_dir_all(&sysroot_path);
    ExitCode::SUCCESS
}

fn random_suffix() -> String {
    // 6 chars from [A-Za-z0-9], deterministic pseudo-random based on time+pid
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    let seed = (now as u64) ^ (process::id() as u64);
    let chars: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut s = String::new();
    let mut x = seed;
    for _ in 0..6 {
        x = x.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        let idx = ((x >> 33) as usize) % chars.len();
        s.push(chars[idx] as char);
    }
    s
}

