fn emit_error<F: FnOnce()>(msg: &str, tip: Option<&str>, usage: F) -> ExitCode {
    eprintln!("error: {msg}");
    eprintln!();
    if let Some(t) = tip {
        eprintln!("  tip: {t}");
        eprintln!();
    }
    usage();
