// Parse arguments for top-level command
fn parse_args() -> Result<TopLevel, ExitCode> {
    let args: Vec<String> = env::args().skip(1).collect();
    let mut i = 0;
    let mut stdio = false;
    let mut _quiet: u8 = 0;

    // Process top-level flags until a subcommand or positional encountered.
    while i < args.len() {
        let a = &args[i];
        if a == "-V" || a == "--version" {
            return Ok(TopLevel::Version);
        } else if a == "-h" || a == "--help" {
            return Ok(TopLevel::HelpMain);
        } else if a == "--stdio" {
            stdio = true;
            i += 1;
        } else if a == "-q" || a == "--quiet" {
            _quiet = _quiet.saturating_add(1);
            i += 1;
        } else if let Some(rest) = a.strip_prefix("-q") {
            // short bundled: -qqq etc (quiet takes no value, and it repeats)
            // -q is ArgAction::Count so can be given as -qqq
            if rest.chars().all(|c| c == 'q') {
                _quiet = _quiet.saturating_add(1 + rest.len() as u8);
                i += 1;
            } else {
                return Err(emit_error(
                    &format!("unexpected argument '{a}' found"),
                    None,
                    cli_err_usage_main,
                ));
            }
        } else if a.starts_with('-') {
            return Err(emit_error(
                &format!("unexpected argument '{a}' found"),
                None,
                cli_err_usage_main,
            ));
        } else {
            break;
        }
    }

    if i >= args.len() {
        // No subcommand - default to run LSP
        return Ok(TopLevel::Run { stdio });
    }

    let sub = &args[i];
    let rest: Vec<String> = args[i + 1..].to_vec();

    match sub.as_str() {
        "check" => parse_check(&rest),
        "clean" => parse_clean(&rest),
        "toolchain" => parse_toolchain(&rest),
        "completions" => parse_completions(&rest),
        "help" => Ok(TopLevel::Help(rest)),
        _ => Err(emit_error(
            &format!("unrecognized subcommand '{sub}'"),
            None,
            cli_err_usage_main,
        )),
    }
}

fn parse_check(args: &[String]) -> Result<TopLevel, ExitCode> {
    let mut path: Option<String> = None;
    let mut all_targets = false;
    let mut all_features = false;
    let mut dash_dash = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if dash_dash {
            if path.is_none() {
                path = Some(a.clone());
                i += 1;
                continue;
            } else {
                return Err(emit_error(
                    &format!("unexpected argument '{a}' found"),
                    None,
                    cli_err_usage_check,
                ));
            }
        }
        if a == "--" {
            dash_dash = true;
            i += 1;
            continue;
        }
        if a == "-h" || a == "--help" {
            print!("{}", help_text::CHECK_HELP.replace("{prog}", &prog_name()));
            process::exit(0);
        }
        if a == "--all-targets" {
            all_targets = true;
            i += 1;
            continue;
        }
        if a == "--all-features" {
            all_features = true;
            i += 1;
            continue;
        }
        if a.starts_with('-') {
            let tip = format!("to pass '{a}' as a value, use '-- {a}'");
            return Err(emit_error(
                &format!("unexpected argument '{a}' found"),
                Some(&tip),
                cli_err_usage_check,
            ));
        }
        if path.is_none() {
            path = Some(a.clone());
            i += 1;
        } else {
            return Err(emit_error(
                &format!("unexpected argument '{a}' found"),
                None,
                cli_err_usage_check,
            ));
        }
    }
    Ok(TopLevel::Check { path, all_targets, all_features })
}

