fn parse_toolchain_install(args: &[String]) -> Result<TopLevel, ExitCode> {
    let mut path: Option<String> = None;
    let mut skip_rustowl = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if a == "-h" || a == "--help" {
            print!("{}", help_text::TOOLCHAIN_INSTALL_HELP.replace("{prog}", &prog_name()));
            process::exit(0);
        }
        if a == "--skip-rustowl-toolchain" {
            skip_rustowl = true;
            i += 1;
            continue;
        }
        if a == "--path" {
            if i + 1 >= args.len() {
                return Err(emit_error(
                    "a value is required for '--path <path>' but none was supplied",
                    None,
                    || {
                        eprintln!("For more information, try '--help'.");
                    },
                ));
            }
            path = Some(args[i + 1].clone());
            i += 2;
            continue;
        }
        if let Some(val) = a.strip_prefix("--path=") {
            if val.is_empty() {
                return Err(emit_error(
                    "a value is required for '--path <path>' but none was supplied",
                    None,
                    || {
                        eprintln!("For more information, try '--help'.");
                    },
                ));
            }
            path = Some(val.to_string());
            i += 1;
            continue;
        }
        if a.starts_with('-') {
            return Err(emit_error(
                &format!("unexpected argument '{a}' found"),
                None,
                cli_err_usage_toolchain_install,
            ));
        }
        return Err(emit_error(
            &format!("unexpected argument '{a}' found"),
            None,
            cli_err_usage_toolchain_install,
