fn parse_completions(args: &[String]) -> Result<TopLevel, ExitCode> {
    let mut shell: Option<Shell> = None;
    let mut shell_raw: Option<String> = None;
    let mut dash_dash = false;
    let mut long_help = false;
    let mut short_help = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if dash_dash {
            if shell.is_none() {
                shell_raw = Some(a.clone());
                shell = Shell::parse(a);
                if shell.is_none() {
                    break;
                }
                i += 1;
                continue;
            } else {
                return Err(emit_error(
                    &format!("unexpected argument '{a}' found"),
                    None,
                    cli_err_usage_completions,
                ));
            }
        }
        if a == "--" {
            dash_dash = true;
            i += 1;
            continue;
        }
        if a == "-h" {
            short_help = true;
            i += 1;
            continue;
        }
        if a == "--help" {
            long_help = true;
            i += 1;
            continue;
        }
        if a.starts_with('-') {
            let tip = format!("to pass '{a}' as a value, use '-- {a}'");
            return Err(emit_error(
                &format!("unexpected argument '{a}' found"),
                Some(&tip),
                cli_err_usage_completions,
            ));
        }
        if shell.is_none() && shell_raw.is_none() {
            shell_raw = Some(a.clone());
            shell = Shell::parse(a);
            if shell.is_none() {
                break;
            }
            i += 1;
        } else {
            return Err(emit_error(
                &format!("unexpected argument '{a}' found"),
                None,
                cli_err_usage_completions,
            ));
        }
    }

    if short_help {
        print!("{}", help_text::COMPLETIONS_SHORT_HELP.replace("{prog}", &prog_name()));
        process::exit(0);
    }
    if long_help {
        print!("{}", help_text::COMPLETIONS_LONG_HELP.replace("{prog}", &prog_name()));
        process::exit(0);
    }

    match shell {
        Some(s) => Ok(TopLevel::Completions(s)),
        None => {
            if let Some(raw) = shell_raw {
                Err(emit_error(
                    &format!(
                        "invalid value '{raw}' for '<SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh, nushell]"
                    ),
                    None,
                    || {
                        eprintln!("For more information, try '--help'.");
                    },
                ))
            } else {
                Err(emit_error(
                    "the following required arguments were not provided:\n  <SHELL>",
                    None,
                    cli_err_usage_completions,
                ))
            }
        }
    }
}

// Handle "help" subcommand and "toolchain help" chain
fn handle_help(args: &[String]) -> ExitCode {
    // Walk the args to find which help to show
    if args.is_empty() {
        print!("{}", help_text::MAIN_HELP.replace("{prog}", &prog_name()));
        return ExitCode::SUCCESS;
    }
    let first = &args[0];
    let rest = &args[1..];
    match first.as_str() {
        "check" => {
            print!("{}", help_text::CHECK_HELP.replace("{prog}", &prog_name()));
            ExitCode::SUCCESS
        }
        "clean" => {
            print!("{}", help_text::CLEAN_HELP.replace("{prog}", &prog_name()));
            ExitCode::SUCCESS
        }
        "completions" => {
            // help for completions uses long form
            print!("{}", help_text::COMPLETIONS_LONG_HELP.replace("{prog}", &prog_name()));
            ExitCode::SUCCESS
        }
        "help" => {
            print!("{}", help_text::HELP_HELP.replace("{prog}", &prog_name()));
            ExitCode::SUCCESS
        }
        "toolchain" => {
            if rest.is_empty() {
                print!("{}", help_text::TOOLCHAIN_HELP.replace("{prog}", &prog_name()));
                ExitCode::SUCCESS
            } else {
                match rest[0].as_str() {
                    "install" => {
                        print!("{}", help_text::TOOLCHAIN_INSTALL_HELP.replace("{prog}", &prog_name()));
                        ExitCode::SUCCESS
                    }
                    "uninstall" => {
                        print!("{}", help_text::TOOLCHAIN_UNINSTALL_HELP.replace("{prog}", &prog_name()));
                        ExitCode::SUCCESS
                    }
                    _ => {
                        eprintln!("error: unrecognized subcommand '{}'", rest[0]);
                        eprintln!();
                        cli_err_usage_toolchain();
                        ExitCode::from(2)
                    }
                }
            }
        }
        _ => {
            eprintln!("error: unrecognized subcommand '{first}'");
            eprintln!();
            cli_err_usage_main();
            ExitCode::from(2)
        }
    }
}

