fn run_clean() -> ExitCode {
    // Find cargo target directory via `cargo metadata --format-version 1 --no-deps`
    let out = Command::new("cargo")
        .args(["metadata", "--format-version", "1", "--no-deps"])
        .stderr(std::process::Stdio::null())
        .output();
    let Ok(out) = out else {
        return ExitCode::SUCCESS;
    };
    if !out.status.success() {
        return ExitCode::SUCCESS;
    }
    let text = String::from_utf8_lossy(&out.stdout);
    // naive parse for "target_directory":"..."
    if let Some(start) = text.find("\"target_directory\":\"") {
        let from = start + "\"target_directory\":\"".len();
        if let Some(end) = text[from..].find('"') {
            let target = &text[from..from + end];
            let owl_dir = PathBuf::from(target).join("owl");
            let _ = std::fs::remove_dir_all(&owl_dir);
        }
    }
    ExitCode::SUCCESS
}

