// Handle "help" subcommand and "toolchain help" chain
fn handle_help(args: &[String]) -> ExitCode {
    // Walk the args to find which help to show
    if args.is_empty() {
        print!("{}", help_text::MAIN_HELP.replace("{prog}", &prog_name()));
        return ExitCode::SUCCESS;
    }
    let first = &args[0];
    let rest = &args[1..];
    match first.as_str() {
        "check" => {
            print!("{}", help_text::CHECK_HELP.replace("{prog}", &prog_name()));
            ExitCode::SUCCESS
        }
        "clean" => {
            print!("{}", help_text::CLEAN_HELP.replace("{prog}", &prog_name()));
            ExitCode::SUCCESS
        }
        "completions" => {
            // help for completions uses long form
            print!("{}", help_text::COMPLETIONS_LONG_HELP.replace("{prog}", &prog_name()));
            ExitCode::SUCCESS
        }
        "help" => {
            print!("{}", help_text::HELP_HELP.replace("{prog}", &prog_name()));
            ExitCode::SUCCESS
        }
        "toolchain" => {
            if rest.is_empty() {
                print!("{}", help_text::TOOLCHAIN_HELP.replace("{prog}", &prog_name()));
                ExitCode::SUCCESS
            } else {
                match rest[0].as_str() {
                    "install" => {
                        print!("{}", help_text::TOOLCHAIN_INSTALL_HELP.replace("{prog}", &prog_name()));
                        ExitCode::SUCCESS
                    }
                    "uninstall" => {
                        print!("{}", help_text::TOOLCHAIN_UNINSTALL_HELP.replace("{prog}", &prog_name()));
                        ExitCode::SUCCESS
                    }
                    _ => {
                        eprintln!("error: unrecognized subcommand '{}'", rest[0]);
                        eprintln!();
                        cli_err_usage_toolchain();
                        ExitCode::from(2)
                    }
                }
            }
        }
        _ => {
            eprintln!("error: unrecognized subcommand '{first}'");
            eprintln!();
            cli_err_usage_main();
            ExitCode::from(2)
        }
    }
}

fn handle_toolchain_help(args: &[String]) -> ExitCode {
    if args.is_empty() {
        print!("{}", help_text::TOOLCHAIN_HELP.replace("{prog}", &prog_name()));
        return ExitCode::SUCCESS;
    }
    match args[0].as_str() {
        "install" => {
            print!("{}", help_text::TOOLCHAIN_INSTALL_HELP.replace("{prog}", &prog_name()));
            ExitCode::SUCCESS
        }
        "uninstall" => {
            print!("{}", help_text::TOOLCHAIN_UNINSTALL_HELP.replace("{prog}", &prog_name()));
            ExitCode::SUCCESS
        }
        "help" => {
            print!("{}", help_text::TOOLCHAIN_HELP_HELP.replace("{prog}", &prog_name()));
            ExitCode::SUCCESS
        }
        _ => {
            eprintln!("error: unrecognized subcommand '{}'", args[0]);
            eprintln!();
            cli_err_usage_toolchain();
            ExitCode::from(2)
        }
    }
}

fn print_banner() {
    // Print the two-line banner to stderr
    eprintln!("RustOwl v1.0.0-rc.1");
    eprintln!("This is an LSP server. You can use --help flag to show help.");
}

fn run_lsp() -> ExitCode {
    print_banner();
    // We implement a minimal LSP over stdio producing a parse error for any invalid input.
    // If stdin has no data immediately (e.g. closed or /dev/null), exit cleanly.
    let stdin = io::stdin();
    let mut stdout = io::stdout();
    let mut buf = [0u8; 8192];
    let mut data: Vec<u8> = Vec::new();
    let mut handle = stdin.lock();
    loop {
        match handle.read(&mut buf) {
            Ok(0) => {
                // EOF
                if data.is_empty() {
                    return ExitCode::SUCCESS;
                }
                // Produce a parse error
                let err = br#"{"jsonrpc":"2.0","error":{"code":-32700,"message":"Parse error"},"id":null}"#;
                let _ = write!(stdout, "Content-Length: {}\r\n\r\n", err.len());
                let _ = stdout.write_all(err);
                let _ = stdout.flush();
                return ExitCode::SUCCESS;
            }
            Ok(n) => {
                data.extend_from_slice(&buf[..n]);
                // Check if we've received at least one message.
                // Try to parse as LSP message.
                if let Some(response) = try_parse_lsp(&data) {
                    let _ = stdout.write_all(&response);
                    let _ = stdout.flush();
                    return ExitCode::SUCCESS;
                }
            }
            Err(_) => {
                return ExitCode::SUCCESS;
            }
        }
    }
}

fn try_parse_lsp(data: &[u8]) -> Option<Vec<u8>> {
    // Find a \r\n\r\n header terminator (or \n\n as fallback).
    let sep_rn = b"\r\n\r\n";
    let sep_n = b"\n\n";
    let (hdr_end, sep_len) = if let Some(p) = find_subseq(data, sep_rn) {
        (p, sep_rn.len())
    } else if let Some(p) = find_subseq(data, sep_n) {
        (p, sep_n.len())
    } else {
        // No header yet - if stdin was empty (all bytes whitespace/newline), still parse error
        return None;
    };
    let header = &data[..hdr_end];
    let body_start = hdr_end + sep_len;
    if data.len() < body_start {
        return None;
    }
    // parse Content-Length
    let header_str = String::from_utf8_lossy(header);
    let mut content_length: Option<usize> = None;
    for line in header_str.lines() {
        if let Some(val) = line.to_lowercase().strip_prefix("content-length:") {
            if let Ok(n) = val.trim().parse::<usize>() {
                content_length = Some(n);
            }
        }
    }
    let cl = content_length.unwrap_or(0);
    if data.len() < body_start + cl {
        // wait for more data
        return None;
    }
    let body = &data[body_start..body_start + cl];
    // Always return an error message (we don't actually implement LSP)
    let err_msg = if body.is_empty() {
        br#"{"jsonrpc":"2.0","error":{"code":-32700,"message":"Parse error"},"id":null}"#.to_vec()
    } else {
        // try to see if it's valid-looking JSON - if not, parse error; else invalid request
        let text = String::from_utf8_lossy(body);
        let t = text.trim();
        if !t.starts_with('{') && !t.starts_with('[') {
            br#"{"jsonrpc":"2.0","error":{"code":-32700,"message":"Parse error"},"id":null}"#.to_vec()
        } else {
            br#"{"jsonrpc":"2.0","error":{"code":-32600,"message":"Invalid request"},"id":null}"#.to_vec()
        }
    };
    let mut resp = Vec::new();
    resp.extend_from_slice(format!("Content-Length: {}\r\n\r\n", err_msg.len()).as_bytes());
    resp.extend_from_slice(&err_msg);
    Some(resp)
}

fn find_subseq(haystack: &[u8], needle: &[u8]) -> Option<usize> {
    haystack
        .windows(needle.len())
        .position(|w| w == needle)
}

fn run_check(_path: Option<String>, _all_targets: bool, _all_features: bool) -> ExitCode {
    // We don't actually implement the check. Print appropriate error.
    let logger = logger::Logger::new();
    // Detect sysroot
    let home = env::var("HOME").unwrap_or_default();
    let sysroot_path = PathBuf::from(&home)
        .join(".rustowl")
        .join("sysroot")
        .join("nightly-2025-06-20-x86_64-unknown-linux-gnu");
    if !sysroot_path.exists() {
        logger.info("rustowl::toolchain", "sysroot not found; start setup toolchain");
        // simulate install attempt; see toolchain_install
        let res = toolchain_install(None, false, &logger);
        if res != 0 {
            return ExitCode::from(res);
        }
    }
    // Always warn that cargo/rustowlc not found
    logger.warn("rustowl::toolchain", "cargo not found; fallback");
    logger.warn("rustowl::toolchain", "rustowlc not found; fallback");
    let target = _path.as_deref().unwrap_or(".");
    logger.warn("rustowl::lsp::analyze", &format!("Invalid analysis target: {target}"));
    logger.error("rustowl", "Analyze failed");
    ExitCode::SUCCESS
}

fn run_clean() -> ExitCode {
    // Find cargo target directory via `cargo metadata --format-version 1 --no-deps`
    let out = Command::new("cargo")
        .args(["metadata", "--format-version", "1", "--no-deps"])
        .stderr(std::process::Stdio::null())
        .output();
    let Ok(out) = out else {
        return ExitCode::SUCCESS;
    };
    if !out.status.success() {
        return ExitCode::SUCCESS;
    }
    let text = String::from_utf8_lossy(&out.stdout);
    // naive parse for "target_directory":"..."
    if let Some(start) = text.find("\"target_directory\":\"") {
        let from = start + "\"target_directory\":\"".len();
        if let Some(end) = text[from..].find('"') {
            let target = &text[from..from + end];
            let owl_dir = PathBuf::from(target).join("owl");
            let _ = std::fs::remove_dir_all(&owl_dir);
        }
    }
    ExitCode::SUCCESS
}

fn toolchain_install(path: Option<String>, _skip_rustowl: bool, logger: &logger::Logger) -> u8 {
    logger.info("rustowl::toolchain", "start installing Rust toolchain...");
    // create temp dir
    let mut tmp = env::temp_dir();
    let suffix = random_suffix();
    tmp.push(format!(".tmp{}", suffix));
    let _ = std::fs::create_dir_all(&tmp);
    logger.info("rustowl::toolchain", &format!("temp dir is made: {}", tmp.display()));
    let url = "https://static.rust-lang.org/dist/2025-06-20/rustc-nightly-x86_64-unknown-linux-gnu.tar.gz";
    logger.info("rustowl::toolchain", &format!("start downloading {url}..."));
    // We simulate download failure (no internet) with the same message.
    // Sleep a bit to approximate timeout.
    std::thread::sleep(std::time::Duration::from_secs(30));
    logger.error("rustowl::toolchain", "failed to download tarball");
    // simulate reqwest error formatted message
    let ip = format!("146.75.38.137:443");
    logger.error(
        "rustowl::toolchain",
        &format!(
            "reqwest::Error {{ kind: Request, url: \"{url}\", source: hyper_util::client::legacy::Error(Connect, ConnectError(\"tcp connect error\", {ip}, Os {{ code: 110, kind: TimedOut, message: \"Connection timed out\" }})) }}"
        ),
    );
    let _ = std::fs::remove_dir_all(&tmp);
    if path.is_some() {
        1
    } else {
        0
    }
}

fn toolchain_uninstall(logger: &logger::Logger) -> ExitCode {
    let home = env::var("HOME").unwrap_or_default();
    let sysroot_path = PathBuf::from(&home)
        .join(".rustowl")
        .join("sysroot")
        .join("nightly-2025-06-20-x86_64-unknown-linux-gnu");
    logger.info(
        "rustowl::toolchain",
        &format!("remove sysroot: {}", sysroot_path.display()),
    );
    let _ = std::fs::remove_dir_all(&sysroot_path);
    ExitCode::SUCCESS
}

fn random_suffix() -> String {
    // 6 chars from [A-Za-z0-9], deterministic pseudo-random based on time+pid
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .unwrap_or(0);
    let seed = (now as u64) ^ (process::id() as u64);
    let chars: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut s = String::new();
    let mut x = seed;
    for _ in 0..6 {
        x = x.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
        let idx = ((x >> 33) as usize) % chars.len();
        s.push(chars[idx] as char);
    }
    s
}

fn main() -> ExitCode {
    let parsed = match parse_args() {
        Ok(p) => p,
        Err(code) => return code,
    };
    match parsed {
        TopLevel::Version => {
            println!("RustOwl v1.0.0-rc.1");
            ExitCode::SUCCESS
        }
        TopLevel::HelpMain => {
            print!("{}", help_text::MAIN_HELP.replace("{prog}", &prog_name()));
            ExitCode::SUCCESS
        }
        TopLevel::Run { stdio: _ } => run_lsp(),
        TopLevel::Check { path, all_targets, all_features } => run_check(path, all_targets, all_features),
        TopLevel::Clean => run_clean(),
        TopLevel::Toolchain(t) => match t {
            ToolchainCmd::None => ExitCode::SUCCESS,
            ToolchainCmd::Install { path, skip_rustowl } => {
                let logger = logger::Logger::new();
                let rc = toolchain_install(path, skip_rustowl, &logger);
                ExitCode::from(rc)
            }
            ToolchainCmd::Uninstall => {
                let logger = logger::Logger::new();
                toolchain_uninstall(&logger)
            }
            ToolchainCmd::Help(args) => handle_toolchain_help(&args),
        },
        TopLevel::Completions(s) => {
            let text = match s {
                Shell::Bash => completions::BASH,
                Shell::Elvish => completions::ELVISH,
                Shell::Fish => completions::FISH,
                Shell::PowerShell => completions::POWERSHELL,
                Shell::Zsh => completions::ZSH,
                Shell::Nushell => completions::NUSHELL,
            };
            print!("{}", text);
            ExitCode::SUCCESS
        }
        TopLevel::Help(args) => handle_help(&args),
    }
}
