fn is_leap(y: i64) -> bool {
    (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0)
}

fn days_in_month(y: i64, m: i64) -> i64 {
    match m {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => if is_leap(y) { 29 } else { 28 },
        _ => 0,
    }
}

fn epoch_to_ymd(mut secs: i64) -> (i64, i64, i64, i64, i64, i64) {
    let day_sec = 86400;
    let s = secs.rem_euclid(day_sec);
    secs -= s;
    let mut days = secs / day_sec;
    let hours = s / 3600;
    let mins = (s / 60) % 60;
    let secs_final = s % 60;
    // 1970-01-01 is day 0 (Thursday)
    let mut y = 1970i64;
    loop {
        let ydays = if is_leap(y) { 366 } else { 365 };
        if days >= ydays {
            days -= ydays;
            y += 1;
        } else {
            break;
        }
    }
    let mut m = 1i64;
    loop {
        let mdays = days_in_month(y, m);
        if days >= mdays {
            days -= mdays;
            m += 1;
        } else {
            break;
        }
    }
    let d = days + 1;
    (y, m, d, hours, mins, secs_final)
}
