use std::io::Write;
use std::sync::atomic::{AtomicU8, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

// Log levels: 0=OFF, 1=ERROR, 2=WARN, 3=INFO, 4=DEBUG, 5=TRACE
// Default: INFO (3). Each -q reduces one step.
static LEVEL: AtomicU8 = AtomicU8::new(3);

pub fn set_quiet(count: u8) {
    let new = 3u8.saturating_sub(count);
    LEVEL.store(new, Ordering::Relaxed);
}

fn enabled(level: u8) -> bool {
    LEVEL.load(Ordering::Relaxed) >= level
}

pub struct Logger;

impl Logger {
    pub fn new() -> Self {
        Self
    }
    fn ts() -> String {
        // Format: 2026-05-07T18:25:57.328Z
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default();
        let secs = now.as_secs() as i64;
        let millis = now.subsec_millis();
        let (y, mo, d, h, mi, s) = epoch_to_ymd(secs);
        format!(
            "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:03}Z",
            y, mo, d, h, mi, s, millis
        )
    }
    fn write(&self, level: &str, module: &str, msg: &str) {
        let mut stderr = std::io::stderr().lock();
        let _ = writeln!(stderr, "{} {} [{}] {}", Self::ts(), level, module, msg);
    }
    pub fn info(&self, module: &str, msg: &str) {
        if enabled(3) {
            self.write("INFO ", module, msg);
        }
    }
    pub fn warn(&self, module: &str, msg: &str) {
        if enabled(2) {
            self.write("WARN ", module, msg);
        }
    }
    pub fn error(&self, module: &str, msg: &str) {
        if enabled(1) {
            self.write("ERROR", module, msg);
        }
    }
}

fn is_leap(y: i64) -> bool {
